CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. Sign-in is per person; publishing identity lives on channels.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown in account menus, not on public videos.
	"display_name" VARCHAR(80) NOT NULL,
	-- ISO 3166-1 alpha-2, used for regional trending and blocked-content rules. Null when never resolved.
	"country_code" CHAR(2),
	-- Account-level ban. Set rather than deleting, because deletion would orphan every comment and video the account owns.
	"is_suspended" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A sign-in identity. A person can own several channels, so nothing public - subscriber counts, uploads, monetisation - hangs off this table.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity. Sign-in is per person; publishing identity lives on channels.';
COMMENT ON COLUMN "users"."display_name" IS 'Name shown in account menus, not on public videos.';
COMMENT ON COLUMN "users"."country_code" IS 'ISO 3166-1 alpha-2, used for regional trending and blocked-content rules. Null when never resolved.';
COMMENT ON COLUMN "users"."is_suspended" IS 'Account-level ban. Set rather than deleting, because deletion would orphan every comment and video the account owns.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE TABLE IF NOT EXISTS "channels" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- User who controls the channel. Transferring a channel updates this column and nothing else.
	"owner_id" BIGINT NOT NULL,
	-- Public @handle used in URLs. Unique across the platform and compared case-insensitively.
	"handle" VARCHAR(40) NOT NULL UNIQUE,
	-- Display name, freely changeable, which is exactly why the handle exists separately.
	"name" VARCHAR(120) NOT NULL,
	-- About-page copy.
	"description" TEXT,
	-- Denormalised counter maintained by the subscription write path. Every channel page and every video page reads it.
	"subscriber_count" INTEGER NOT NULL DEFAULT 0,
	-- none | applied | enabled | suspended. Channel-level eligibility; individual videos can still be demonetised.
	"monetization_status" VARCHAR(24) NOT NULL DEFAULT 'none',
	-- ISO 4217 currency earnings are paid in. Null until monetisation is enabled.
	"payout_currency" CHAR(3),
	-- Channel creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "channels" IS 'The public publishing identity. Videos, playlists, subscriptions and money all key on a channel rather than a user, so one person running three channels needs no special cases.';
COMMENT ON COLUMN "channels"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "channels"."owner_id" IS 'User who controls the channel. Transferring a channel updates this column and nothing else.';
COMMENT ON COLUMN "channels"."handle" IS 'Public @handle used in URLs. Unique across the platform and compared case-insensitively.';
COMMENT ON COLUMN "channels"."name" IS 'Display name, freely changeable, which is exactly why the handle exists separately.';
COMMENT ON COLUMN "channels"."description" IS 'About-page copy.';
COMMENT ON COLUMN "channels"."subscriber_count" IS 'Denormalised counter maintained by the subscription write path. Every channel page and every video page reads it.';
COMMENT ON COLUMN "channels"."monetization_status" IS 'none | applied | enabled | suspended. Channel-level eligibility; individual videos can still be demonetised.';
COMMENT ON COLUMN "channels"."payout_currency" IS 'ISO 4217 currency earnings are paid in. Null until monetisation is enabled.';
COMMENT ON COLUMN "channels"."created_at" IS 'Channel creation time.';

CREATE INDEX "idx_channels_owner"
ON "channels" ("owner_id");

CREATE TABLE IF NOT EXISTS "videos" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Publishing channel.
	"channel_id" BIGINT NOT NULL,
	-- Video title.
	"title" VARCHAR(200) NOT NULL,
	-- Description body, including the timestamps and links creators put there.
	"description" TEXT,
	-- private | unlisted | public | scheduled. Defaults to private so an upload is never briefly public while processing.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'private',
	-- uploading | processing | ready | rejected | removed. Separate from visibility: a public video can still be unwatchable while transcoding.
	"status" VARCHAR(20) NOT NULL DEFAULT 'uploading',
	-- Runtime, known only once the source is probed. Null while uploading.
	"duration_seconds" INTEGER,
	-- When it became publicly visible. Null for a private or still-processing upload, which is why it is not the same as the row created time.
	"published_at" TIMESTAMPTZ,
	-- Denormalised lifetime views, refreshed from the daily rollup. This is the number every listing renders, which is the whole reason it is a column.
	"view_count" BIGINT NOT NULL DEFAULT 0,
	-- Denormalised like tally, maintained by the reaction write path.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised comment tally, including replies.
	"comment_count" INTEGER NOT NULL DEFAULT 0,
	-- Self-declared child-directed flag. Disables personalised ads and comments regardless of the monetisation row.
	"is_made_for_kids" BOOLEAN NOT NULL DEFAULT false,
	-- When the upload record was created.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "videos" IS 'One upload. The counter columns are caches of other tables, never the source of truth - they exist because a search results page cannot afford twenty aggregate queries.';
COMMENT ON COLUMN "videos"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "videos"."channel_id" IS 'Publishing channel.';
COMMENT ON COLUMN "videos"."title" IS 'Video title.';
COMMENT ON COLUMN "videos"."description" IS 'Description body, including the timestamps and links creators put there.';
COMMENT ON COLUMN "videos"."visibility" IS 'private | unlisted | public | scheduled. Defaults to private so an upload is never briefly public while processing.';
COMMENT ON COLUMN "videos"."status" IS 'uploading | processing | ready | rejected | removed. Separate from visibility: a public video can still be unwatchable while transcoding.';
COMMENT ON COLUMN "videos"."duration_seconds" IS 'Runtime, known only once the source is probed. Null while uploading.';
COMMENT ON COLUMN "videos"."published_at" IS 'When it became publicly visible. Null for a private or still-processing upload, which is why it is not the same as the row created time.';
COMMENT ON COLUMN "videos"."view_count" IS 'Denormalised lifetime views, refreshed from the daily rollup. This is the number every listing renders, which is the whole reason it is a column.';
COMMENT ON COLUMN "videos"."like_count" IS 'Denormalised like tally, maintained by the reaction write path.';
COMMENT ON COLUMN "videos"."comment_count" IS 'Denormalised comment tally, including replies.';
COMMENT ON COLUMN "videos"."is_made_for_kids" IS 'Self-declared child-directed flag. Disables personalised ads and comments regardless of the monetisation row.';
COMMENT ON COLUMN "videos"."created_at" IS 'When the upload record was created.';

CREATE INDEX "idx_videos_channel_published"
ON "videos" ("channel_id", "published_at");
CREATE INDEX "idx_videos_visibility_published"
ON "videos" ("visibility", "published_at");

CREATE TABLE IF NOT EXISTS "video_renditions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Source video.
	"video_id" BIGINT NOT NULL,
	-- 144p | 360p | 720p | 1080p | 2160p. The rung on the ladder, as offered in the quality menu.
	"label" VARCHAR(16) NOT NULL,
	-- Codec of the encode, e.g. h264, vp9, av1. The same rung is encoded several times so old devices still get a playable stream.
	"codec" VARCHAR(24) NOT NULL,
	-- Pixel width of the encode.
	"width" SMALLINT NOT NULL,
	-- Pixel height of the encode.
	"height" SMALLINT NOT NULL,
	-- Average bitrate, used by the player to pick a rung for the measured bandwidth.
	"bitrate_kbps" INTEGER NOT NULL,
	-- Object storage key of the encoded file. The bytes live in object storage; only the pointer is relational.
	"storage_key" VARCHAR(300) NOT NULL,
	-- queued | encoding | ready | failed. A video becomes watchable when its first rung reaches ready, not when all of them do.
	"status" VARCHAR(20) NOT NULL DEFAULT 'queued',
	PRIMARY KEY("id")
);

COMMENT ON TABLE "video_renditions" IS 'One encoded file per quality rung per codec. Rows appear over time, which is why playback starts at 360p and higher qualities show up minutes later.';
COMMENT ON COLUMN "video_renditions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "video_renditions"."video_id" IS 'Source video.';
COMMENT ON COLUMN "video_renditions"."label" IS '144p | 360p | 720p | 1080p | 2160p. The rung on the ladder, as offered in the quality menu.';
COMMENT ON COLUMN "video_renditions"."codec" IS 'Codec of the encode, e.g. h264, vp9, av1. The same rung is encoded several times so old devices still get a playable stream.';
COMMENT ON COLUMN "video_renditions"."width" IS 'Pixel width of the encode.';
COMMENT ON COLUMN "video_renditions"."height" IS 'Pixel height of the encode.';
COMMENT ON COLUMN "video_renditions"."bitrate_kbps" IS 'Average bitrate, used by the player to pick a rung for the measured bandwidth.';
COMMENT ON COLUMN "video_renditions"."storage_key" IS 'Object storage key of the encoded file. The bytes live in object storage; only the pointer is relational.';
COMMENT ON COLUMN "video_renditions"."status" IS 'queued | encoding | ready | failed. A video becomes watchable when its first rung reaches ready, not when all of them do.';

CREATE UNIQUE INDEX "uq_renditions_video_label_codec"
ON "video_renditions" ("video_id", "label", "codec");

CREATE TABLE IF NOT EXISTS "video_view_daily" (
	-- Video being counted.
	"video_id" BIGINT,
	-- UTC calendar day of the bucket. Keying on (video, day) is what turns billions of raw view events into one small row per video per day.
	"view_date" DATE,
	-- Qualified views in the bucket, after bot filtering and the minimum-watch-time rule.
	"views" BIGINT NOT NULL DEFAULT 0,
	-- Approximate distinct viewers, from a sketch rather than an exact count - exactness here costs far more than it is worth.
	"unique_viewers" BIGINT NOT NULL DEFAULT 0,
	-- Total seconds watched. The metric the ranking system actually optimises; raw views are the vanity number.
	"watch_time_seconds" BIGINT NOT NULL DEFAULT 0,
	-- Mean fraction of the video watched. The one place a float is right, because it is a statistic and not money.
	"average_view_ratio" REAL,
	PRIMARY KEY("video_id", "view_date")
);

COMMENT ON TABLE "video_view_daily" IS 'Daily rollup written by the ingestion pipeline from the raw view stream, which never lands in this database. Lifetime counts are a sum of these rows, cached back onto videos.view_count.';
COMMENT ON COLUMN "video_view_daily"."video_id" IS 'Video being counted.';
COMMENT ON COLUMN "video_view_daily"."view_date" IS 'UTC calendar day of the bucket. Keying on (video, day) is what turns billions of raw view events into one small row per video per day.';
COMMENT ON COLUMN "video_view_daily"."views" IS 'Qualified views in the bucket, after bot filtering and the minimum-watch-time rule.';
COMMENT ON COLUMN "video_view_daily"."unique_viewers" IS 'Approximate distinct viewers, from a sketch rather than an exact count - exactness here costs far more than it is worth.';
COMMENT ON COLUMN "video_view_daily"."watch_time_seconds" IS 'Total seconds watched. The metric the ranking system actually optimises; raw views are the vanity number.';
COMMENT ON COLUMN "video_view_daily"."average_view_ratio" IS 'Mean fraction of the video watched. The one place a float is right, because it is a statistic and not money.';

CREATE INDEX "idx_view_daily_date_views"
ON "video_view_daily" ("view_date", "views");

CREATE TABLE IF NOT EXISTS "reactions" (
	-- Video reacted to.
	"video_id" BIGINT,
	-- Reacting account. The composite key makes a second like from the same person an upsert rather than a duplicate.
	"user_id" BIGINT,
	-- 1 for like, -1 for dislike. A number rather than two tables, so flipping a reaction is one update.
	"value" SMALLINT NOT NULL,
	-- When the reaction was last set.
	"reacted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("video_id", "user_id")
);

COMMENT ON TABLE "reactions" IS 'Likes and dislikes in one table. Storing the row is what makes "liked videos" a real list and lets the like button render correctly; the aggregate lives on videos.like_count.';
COMMENT ON COLUMN "reactions"."video_id" IS 'Video reacted to.';
COMMENT ON COLUMN "reactions"."user_id" IS 'Reacting account. The composite key makes a second like from the same person an upsert rather than a duplicate.';
COMMENT ON COLUMN "reactions"."value" IS '1 for like, -1 for dislike. A number rather than two tables, so flipping a reaction is one update.';
COMMENT ON COLUMN "reactions"."reacted_at" IS 'When the reaction was last set.';

CREATE INDEX "idx_reactions_user_recent"
ON "reactions" ("user_id", "reacted_at");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Video being commented on, denormalised onto replies too so a video thread loads in one query.
	"video_id" BIGINT NOT NULL,
	-- Channel that wrote the comment. People comment as a channel, not as a user account.
	"author_channel_id" BIGINT NOT NULL,
	-- Comment being replied to. Null for a top-level comment. Only one level of nesting is allowed: a reply to a reply attaches to the same parent.
	"parent_id" BIGINT,
	-- Comment text.
	"body" TEXT NOT NULL,
	-- Denormalised likes, used to order the default "top comments" view.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- Denormalised replies on a top-level comment, so the "View 42 replies" affordance needs no count query.
	"reply_count" INTEGER NOT NULL DEFAULT 0,
	-- Held for review by a filter or channel setting. Hidden from everyone except the author and the moderator.
	"is_held" BOOLEAN NOT NULL DEFAULT false,
	-- Post time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Threads capped at one level of nesting. Capping is a product decision that the schema then makes cheap: a thread page is two indexed reads, not a recursive walk of arbitrary depth.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."video_id" IS 'Video being commented on, denormalised onto replies too so a video thread loads in one query.';
COMMENT ON COLUMN "comments"."author_channel_id" IS 'Channel that wrote the comment. People comment as a channel, not as a user account.';
COMMENT ON COLUMN "comments"."parent_id" IS 'Comment being replied to. Null for a top-level comment. Only one level of nesting is allowed: a reply to a reply attaches to the same parent.';
COMMENT ON COLUMN "comments"."body" IS 'Comment text.';
COMMENT ON COLUMN "comments"."like_count" IS 'Denormalised likes, used to order the default "top comments" view.';
COMMENT ON COLUMN "comments"."reply_count" IS 'Denormalised replies on a top-level comment, so the "View 42 replies" affordance needs no count query.';
COMMENT ON COLUMN "comments"."is_held" IS 'Held for review by a filter or channel setting. Hidden from everyone except the author and the moderator.';
COMMENT ON COLUMN "comments"."created_at" IS 'Post time.';

CREATE INDEX "idx_comments_thread_top"
ON "comments" ("video_id", "parent_id", "like_count");
CREATE INDEX "idx_comments_replies"
ON "comments" ("parent_id", "created_at");

CREATE TABLE IF NOT EXISTS "subscriptions" (
	-- User subscribing.
	"subscriber_id" BIGINT,
	-- Channel subscribed to. Composite key, so subscribing twice is impossible.
	"channel_id" BIGINT,
	-- all | personalized | none. The bell setting, which decides push notifications independently of whether uploads reach the feed.
	"notify" VARCHAR(16) NOT NULL DEFAULT 'personalized',
	-- When the subscription started; the subscriptions feed only surfaces uploads after this point for new subscribers.
	"subscribed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("subscriber_id", "channel_id")
);

COMMENT ON TABLE "subscriptions" IS 'The fan-out edge. Everything expensive on the platform - the subscriptions feed, upload notifications - is a traversal of this table, which is why it carries no payload beyond the bell setting.';
COMMENT ON COLUMN "subscriptions"."subscriber_id" IS 'User subscribing.';
COMMENT ON COLUMN "subscriptions"."channel_id" IS 'Channel subscribed to. Composite key, so subscribing twice is impossible.';
COMMENT ON COLUMN "subscriptions"."notify" IS 'all | personalized | none. The bell setting, which decides push notifications independently of whether uploads reach the feed.';
COMMENT ON COLUMN "subscriptions"."subscribed_at" IS 'When the subscription started; the subscriptions feed only surfaces uploads after this point for new subscribers.';

CREATE INDEX "idx_subscriptions_channel_time"
ON "subscriptions" ("channel_id", "subscribed_at");

CREATE TABLE IF NOT EXISTS "playlists" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Channel that owns the list.
	"owner_channel_id" BIGINT NOT NULL,
	-- Playlist title.
	"title" VARCHAR(160) NOT NULL,
	-- Optional description.
	"description" TEXT,
	-- private | unlisted | public.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'private',
	-- watch_later | liked | history when this is a built-in list, null for a user-created one. Built-ins are rows here so the client has one playlist renderer, not two.
	"system_kind" VARCHAR(24),
	-- Cached item count shown on the thumbnail overlay.
	"video_count" INTEGER NOT NULL DEFAULT 0,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "playlists" IS 'User playlists and the built-in lists in one table. Watch Later is just a playlist with system_kind set, which removes an entire parallel code path from the client.';
COMMENT ON COLUMN "playlists"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "playlists"."owner_channel_id" IS 'Channel that owns the list.';
COMMENT ON COLUMN "playlists"."title" IS 'Playlist title.';
COMMENT ON COLUMN "playlists"."description" IS 'Optional description.';
COMMENT ON COLUMN "playlists"."visibility" IS 'private | unlisted | public.';
COMMENT ON COLUMN "playlists"."system_kind" IS 'watch_later | liked | history when this is a built-in list, null for a user-created one. Built-ins are rows here so the client has one playlist renderer, not two.';
COMMENT ON COLUMN "playlists"."video_count" IS 'Cached item count shown on the thumbnail overlay.';
COMMENT ON COLUMN "playlists"."created_at" IS 'Creation time.';

CREATE UNIQUE INDEX "uq_playlists_channel_system"
ON "playlists" ("owner_channel_id", "system_kind");

CREATE TABLE IF NOT EXISTS "playlist_items" (
	-- Surrogate primary key. Not a (playlist, video) key, because the same video may appear twice in one list.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent playlist.
	"playlist_id" BIGINT NOT NULL,
	-- Video in the list.
	"video_id" BIGINT NOT NULL,
	-- Explicit zero-based order. Reordering rewrites the affected range in one transaction.
	"position" INTEGER NOT NULL,
	-- When it was added; the default sort for Watch Later, where nobody drags rows.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "playlist_items" IS 'Ordered membership. A removed or privated video keeps its row and renders as unavailable, because silently shrinking someone list is worse than showing them what is gone.';
COMMENT ON COLUMN "playlist_items"."id" IS 'Surrogate primary key. Not a (playlist, video) key, because the same video may appear twice in one list.';
COMMENT ON COLUMN "playlist_items"."playlist_id" IS 'Parent playlist.';
COMMENT ON COLUMN "playlist_items"."video_id" IS 'Video in the list.';
COMMENT ON COLUMN "playlist_items"."position" IS 'Explicit zero-based order. Reordering rewrites the affected range in one transaction.';
COMMENT ON COLUMN "playlist_items"."added_at" IS 'When it was added; the default sort for Watch Later, where nobody drags rows.';

CREATE UNIQUE INDEX "uq_playlist_items_position"
ON "playlist_items" ("playlist_id", "position");
CREATE INDEX "idx_playlist_items_video"
ON "playlist_items" ("video_id");

CREATE TABLE IF NOT EXISTS "video_monetization" (
	-- Video this applies to. One row per video, which is what makes it a one-to-one extension rather than more columns on a hot table.
	"video_id" BIGINT,
	-- Whether ads may serve at all. False for a monetised channel whose video failed review.
	"is_monetized" BOOLEAN NOT NULL DEFAULT false,
	-- pending_review | eligible | limited | ineligible. Limited means advertiser-unfriendly, which serves fewer ads rather than none.
	"ad_state" VARCHAR(24) NOT NULL DEFAULT 'pending_review',
	-- Comma-separated enabled formats: preroll, midroll, overlay, skippable. Null while review is pending.
	"ad_formats" VARCHAR(80),
	-- Whether the creator completed the content questionnaire. Skipping it routes the video to manual review.
	"self_certified" BOOLEAN NOT NULL DEFAULT false,
	-- none | claimed | disputed | blocked. A copyright claim redirects revenue without taking the video down.
	"claim_state" VARCHAR(24) NOT NULL DEFAULT 'none',
	-- When review last completed. Null while pending.
	"reviewed_at" TIMESTAMPTZ,
	PRIMARY KEY("video_id")
);

COMMENT ON TABLE "video_monetization" IS 'Ad eligibility as a separate row per video. It changes on a different schedule from the video metadata, is read only by the ad path, and keeps a wide, rarely-needed set of columns off the videos table.';
COMMENT ON COLUMN "video_monetization"."video_id" IS 'Video this applies to. One row per video, which is what makes it a one-to-one extension rather than more columns on a hot table.';
COMMENT ON COLUMN "video_monetization"."is_monetized" IS 'Whether ads may serve at all. False for a monetised channel whose video failed review.';
COMMENT ON COLUMN "video_monetization"."ad_state" IS 'pending_review | eligible | limited | ineligible. Limited means advertiser-unfriendly, which serves fewer ads rather than none.';
COMMENT ON COLUMN "video_monetization"."ad_formats" IS 'Comma-separated enabled formats: preroll, midroll, overlay, skippable. Null while review is pending.';
COMMENT ON COLUMN "video_monetization"."self_certified" IS 'Whether the creator completed the content questionnaire. Skipping it routes the video to manual review.';
COMMENT ON COLUMN "video_monetization"."claim_state" IS 'none | claimed | disputed | blocked. A copyright claim redirects revenue without taking the video down.';
COMMENT ON COLUMN "video_monetization"."reviewed_at" IS 'When review last completed. Null while pending.';

CREATE TABLE IF NOT EXISTS "community_posts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Posting channel.
	"channel_id" BIGINT NOT NULL,
	-- Post text.
	"body" TEXT NOT NULL,
	-- Video shared in the post. Null for a text, image or poll post.
	"attached_video_id" BIGINT,
	-- Poll choices with their tallies, kept as JSON because nothing else joins to an option and a poll is read whole or not at all.
	"poll_options" JSON,
	-- Denormalised likes.
	"like_count" INTEGER NOT NULL DEFAULT 0,
	-- public | members_only. Members-only posts are the visible half of channel memberships.
	"visibility" VARCHAR(16) NOT NULL DEFAULT 'public',
	-- Post time; the community tab is a reverse-chronological read on this.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "community_posts" IS 'The text-and-poll side of a channel. It deliberately does not reuse videos: a post has no duration, no renditions and no ad eligibility, and squeezing it in would make three tables mostly null.';
COMMENT ON COLUMN "community_posts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "community_posts"."channel_id" IS 'Posting channel.';
COMMENT ON COLUMN "community_posts"."body" IS 'Post text.';
COMMENT ON COLUMN "community_posts"."attached_video_id" IS 'Video shared in the post. Null for a text, image or poll post.';
COMMENT ON COLUMN "community_posts"."poll_options" IS 'Poll choices with their tallies, kept as JSON because nothing else joins to an option and a poll is read whole or not at all.';
COMMENT ON COLUMN "community_posts"."like_count" IS 'Denormalised likes.';
COMMENT ON COLUMN "community_posts"."visibility" IS 'public | members_only. Members-only posts are the visible half of channel memberships.';
COMMENT ON COLUMN "community_posts"."created_at" IS 'Post time; the community tab is a reverse-chronological read on this.';

CREATE INDEX "idx_community_posts_channel_time"
ON "community_posts" ("channel_id", "created_at");

